fn find_port(config: &[(&str, u16)]) -> Option<u16> {
    config.iter().find(|(key, _)| *key == "port").map(|(_, value)| *value)
}

fn main() {
    let config = [("host", 80)];
    let port: u16 = find_port(&config);
    println!("{}", port + 1);
}

